// ---------------------------------------------------------------------------
// QuarterOfAnthropic (wip-anthropic, cut 6). Works in Progress style (styles/works-in-progress.md; kit
// generated/components/kits/works-in-progress/wipShared.tsx).
// Opaque 1080x1920, 24 fps, 189 frames.
//
// CHECK LINE: "All of San Francisco's IPOs, ever, fill just one tile of a block of four; the whole block is Anthropic.
// A viewer with no sound says 'everything SF ever listed is a quarter of this one'."
//
// THE LINE: "If you were to add up every single IPO San Francisco has ever had, it would add up to only one quarter of
// the IPO that Anthropic is about to have."
// WORD -> FRAME: If 0 · you 3 · were 5 · to 8 · add 10 · up 13 · every 17 · single 25 · IPO 35 · San 42 · Francisco 51 ·
// has 61 · ever 67 · had 75 · it 87 · would 90 · add 93 · up 97 · to 103 · only 106 · one 112 · quarter 124 · of 144 ·
// the 146 · IPO 148 · that 156 · Anthropic 163 · is 172 · about 177 · to 181 · have 184
// DURATION: slot 6.000-13.875 s = 7.875 s x 24 = 189 frames.
//
// THE MOTION: a sheet of postage stamps. Close on a square stamp whose picture is night-time San Francisco, the camera
// easing back while twelve real IPO logos on small stamps are dealt onto the bay, one by one, then quicker, in a tidy grid
// under the skyline, the last on "had". The small stamps flatten into it and the camera pulls
// back to show one finished perforated tile. Three blank tiles of the same size slide in and meet it along shared
// perforations ("quarter"); a clay press sweeps across them, leaving Anthropic's mark and wordmark in bare paper, on "Anthropic". The
// SF tile stays untouched in the payoff.
// Contact frames: stamps 14, 23, 31, 38, 44, 49, 54, 58, 62, 66, 69, 72 (each flat 5 frames on); top
// tile joins 122, right 124, diagonal 124; the press starts 144 and is off the block at 162. A day cut-out of the real
// city lies along the page's foot on a far plane, below the second caption band, and rises as the camera pulls back.
// SPOT INK: indigo = the logos, printed base; clay = Anthropic only. No postmark in this cut.
//
// SOURCES: animation_source/assets_raw/SOURCES.txt. Logos and IPOs (Wikipedia article and infobox, checked 2026-11-02):
// Levi Strauss 1971, Salesforce 2004, Yelp 2012, Twitter 2013, Square 2015, Dropbox 2018, Uber, Lyft, Pinterest 2019,
// Unity, Airbnb, DoorDash 2020, all HQ San Francisco at listing. Fitbit (verified) is left out only so the grid is a clean
// 4x3; Slack was a direct listing, not an IPO; Gap discarded. Anthropic mark and wordmark: assets_raw/anthropic/ (lobehub).
// Print: images/07.8b_SanFrancisco_SFSkylineNight.jpg (Commons, Cgbriggs19, CC BY-SA 4.0) through
// scripts/clips/wip-anthropic/bake-quarter-sf.py (its own soft grade); the water below the shore is the photo's own
// water stretched down, and the stamps cover it. Ground strip: images/07.8a_SanFrancisco_SFSkylineEmbarcadero2022.jpg
// (Commons, Benoit Prieur, CC0) through bake-quarter-ground.py and bake-photo.py. "One quarter" is the speaker's figure, not verified: no figures on screen.
// ---------------------------------------------------------------------------
import React from "react";
import { Easing, interpolate, random, useCurrentFrame } from "remotion";
import { z } from "zod";
import {
  CaptionBandsDebug,
  CutOut,
  INDIGO,
  InkPrint,
  PaperGround,
  PrintPhoto,
  Stamp,
  WipFilmLife,
  WipPlane,
  runWipCamera,
  slide,
  stampPress,
} from "../kits/works-in-progress/wipShared";

export const FPS = 24;
export const DURATION = 189;
export const schema = z.object({ bands: z.boolean() });
export const defaultProps = schema.parse({ bands: false });

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// The block, in world px. T = one tile; SF is lower-left, centred on (CX, CY).
const T = 760;
const CX = 540;
const CY = 940;
const B = 34; // the tiles' paper border
const PITCH = T / 13;
const X0 = CX - T / 2;
const XM = CX + T / 2;
const X2 = CX + (3 * T) / 2;
const Y0 = CY - (3 * T) / 2;
const YM = CY - T / 2;
const Y2 = CY + T / 2;

// Camera. Final wide: block 2T x 0.618 = 940 px, y 130-1070, so block centre (XM, YM) sits at screen (540, 600):
// y = YM + 360 / 0.618. In the grid state (k about 1.2) the tile's stamps end at or above y 1070: tile top at y 205.
const K_WIDE = 0.618;
const K_GRID = 1.2;
const camAt = runWipCamera(
  [
    { f: -30, x: CX, y: CY + 40, k: 1.72 },
    { f: 6, x: CX, y: CY + 95, k: 1.5 }, // the horizon stays near y 700-800 through f12
    { f: 36, x: CX, y: YM + (960 - 205) / K_GRID, k: K_GRID },
    { f: 84, x: CX + 6, y: YM + (960 - 215) / 1.16, k: 1.16, ease: "linear" },
    // the pull-back reaches the slow drift at f118 and never stops: it runs through the pause into the press and the creep
    { f: 118, x: XM - 12, y: YM + 385 / 0.68, k: 0.68 },
    { f: DURATION, x: XM, y: YM + 360 / K_WIDE, k: K_WIDE - 0.008, ease: "linear" },
  ],
  DURATION,
);

// The ground strip: a far plane, so it scales little under the camera. Its top rises from about y 1640 at f0 to y 1470 at
// the end, and the wave cut along its bottom lies just above the frame's bottom edge there. See the bands check.
const GROUND_D = 4;
const GROUND_W = 1620;
const GROUND_ASPECT = 3.3003;
const GROUND_TOP = CY + 671;
const GROUND_X = 640;

