  DoorDash: { box: "0 0 154 18", w: 154, h: 18, svg: "<path d=\"M44.674 5.074v7.865h1.961a3.743 3.743 0 0 0 2.667-1.174A3.939 3.939 0 0 0 50.377 9a3.872 3.872 0 0 0-1.06-2.777 3.677 3.677 0 0 0-2.682-1.15h-1.96zm1.961-2.466c3.655 0 6.42 2.832 6.42 6.392 0 3.56-2.765 6.408-6.42 6.408H42.31a.314.314 0 0 1-.31-.318V2.939c0-.176.139-.319.31-.319l4.325-.012zm15.841 10.605c1.66.005 3.159-1.016 3.798-2.587a4.285 4.285 0 0 0-.878-4.587 4.027 4.027 0 0 0-4.47-.922C59.392 5.765 58.39 7.298 58.387 9c0 2.32 1.828 4.202 4.09 4.213m0-10.895c3.847 0 6.788 3.032 6.788 6.682 0 3.65-2.941 6.682-6.789 6.682-3.847 0-6.763-3.017-6.763-6.682 0-3.665 2.941-6.682 6.763-6.682M78.61 13.213c2.263-.006 4.094-1.89 4.092-4.21-.003-2.322-1.838-4.202-4.1-4.203-2.264 0-4.1 1.879-4.103 4.2 0 1.118.433 2.19 1.204 2.98a4.056 4.056 0 0 0 2.906 1.233m0-10.895c3.835 0 6.776 3.017 6.776 6.682 0 3.665-2.953 6.682-6.776 6.682-3.822 0-6.788-3.017-6.788-6.682 0-3.665 2.941-6.682 6.788-6.682m15.746 2.756H91.59v3.385h2.765a1.6 1.6 0 0 0 1.188-.453c.32-.31.502-.74.506-1.192a1.703 1.703 0 0 0-.48-1.246 1.616 1.616 0 0 0-1.214-.491v-.003zm-5.44-2.135c0-.176.14-.319.311-.319h5.206c2.482 0 4.278 1.865 4.278 4.207.019 1.584-.846 3.039-2.227 3.748l2.401 4.353a.325.325 0 0 1 .012.34.308.308 0 0 1-.294.156h-2.107a.31.31 0 0 1-.282-.172l-2.314-4.308H91.58v4.136a.314.314 0 0 1-.31.319h-2.03a.314.314 0 0 1-.31-.319l-.014-12.14zm16.767 2.195V13h1.96a3.743 3.743 0 0 0 2.668-1.17 3.938 3.938 0 0 0 1.077-2.763 3.872 3.872 0 0 0-1.057-2.782 3.677 3.677 0 0 0-2.687-1.15l-1.961-.001zm1.96-2.469c3.655 0 6.42 2.835 6.42 6.402s-2.765 6.402-6.42 6.402h-4.312a.314.314 0 0 1-.31-.319V3c0-.177.139-.32.31-.32l4.313-.015zm14.576 3.128l-1.517 4.206h3.031l-1.514-4.206zm-2.407 6.583l-.993 2.8a.31.31 0 0 1-.31.22h-2.154a.307.307 0 0 1-.283-.134.325.325 0 0 1-.027-.318l4.654-12.139a.31.31 0 0 1 .31-.21h2.41a.31.31 0 0 1 .311.21l4.654 12.139a.325.325 0 0 1-.028.318.307.307 0 0 1-.283.133h-2.153a.31.31 0 0 1-.31-.22l-.993-2.8h-4.805zm11.069-6.31c0-2.01 1.694-3.748 4.369-3.748a5.457 5.457 0 0 1 3.88 1.499.322.322 0 0 1 0 .468L137.936 5.5a.306.306 0 0 1-.44 0 3.097 3.097 0 0 0-2.07-.837c-1.07 0-1.861.637-1.861 1.372 0 2.376 6.323 1.005 6.323 5.577-.003 2.317-1.71 4.07-4.728 4.07a6.25 6.25 0 0 1-4.511-1.858.322.322 0 0 1 0-.468l1.154-1.184a.307.307 0 0 1 .45 0 3.935 3.935 0 0 0 2.727 1.14c1.337 0 2.218-.732 2.218-1.649 0-2.377-6.32-1.005-6.32-5.578m20.476-3.162v4.804h-5.352V2.923a.314.314 0 0 0-.31-.318h-2.03a.314.314 0 0 0-.31.318V15.06c0 .176.14.319.31.319h2.03c.17 0 .31-.143.31-.319v-4.88h5.348v4.88c0 .176.14.319.31.319h2.03c.171 0 .31-.143.31-.319V2.923a.314.314 0 0 0-.31-.318h-2.03a.314.314 0 0 0-.306.318zM30.605 4.225C29.197 1.615 26.442-.01 23.446 0H.778a.78.78 0 0 0-.716.478.763.763 0 0 0 .168.836l4.938 4.9c.436.434 1.03.677 1.648.677h15.98c1.139-.012 2.07.89 2.082 2.013.012 1.123-.901 2.043-2.04 2.054H11.821a.78.78 0 0 0-.718.476.763.763 0 0 0 .167.838l4.941 4.904a2.34 2.34 0 0 0 1.648.676h4.983c6.483 0 11.385-6.84 7.763-13.63\" fill=\"currentColor\"/>" },
