// assets_raw/anthropic/Anthropic_mark_lobehub.svg, viewBox 0 0 24 24, glyph box x 0-24, y 3.52-20.
const MARK = "M13.827 3.52h3.603L24 20h-3.603l-6.57-16.48zm-7.258 0h3.767L16.906 20h-3.674l-1.343-3.461H5.017l-1.344 3.46H0L6.57 3.522zm4.132 9.959L8.453 7.687 6.205 13.48H10.7z";

// The grid: 4 x 3 landscape stamps on the bay, under the skyline, in tile px. `fit` = the logo's share of the stamp's inner box.
const SW = 160;
const SH = 110;
const GX = 9.33;
const GY = 9;
const GRID_X = B + 12;
const GRID_Y = 360;
type LogoName = keyof typeof LOGOS;
const DEAL: { name: LogoName; col: number; row: number; contact: number; fit: number }[] = [
  { name: "Uber", col: 0, row: 0, contact: 14, fit: 0.86 },
  { name: "Salesforce", col: 1, row: 0, contact: 23, fit: 1 },
  { name: "Airbnb", col: 2, row: 0, contact: 31, fit: 1 },
  { name: "Lyft", col: 3, row: 0, contact: 38, fit: 0.84 },
  { name: "Dropbox", col: 0, row: 1, contact: 44, fit: 1 },
  { name: "Twitter", col: 1, row: 1, contact: 49, fit: 0.95 },
  { name: "Levis", col: 2, row: 1, contact: 54, fit: 1 },
  { name: "Yelp", col: 3, row: 1, contact: 58, fit: 1 },
  { name: "Pinterest", col: 0, row: 2, contact: 62, fit: 1 },
  { name: "Square", col: 1, row: 2, contact: 66, fit: 1 },
  { name: "DoorDash", col: 2, row: 2, contact: 69, fit: 1 },
  { name: "Unity", col: 3, row: 2, contact: 72, fit: 1 },
];

const stampCentre = (col: number, row: number) => ({
  x: X0 + GRID_X + SW / 2 + col * (SW + GX),
  y: YM + GRID_Y + SH / 2 + row * (SH + GY),
});

const Logo: React.FC<{ name: LogoName; fit: number; seed: string }> = ({ name, fit, seed }) => {
  const logo = LOGOS[name];
  const boxW = SW - 2 * 7 - 12;
  const boxH = SH - 2 * 7 - 12;
  const s = Math.min(boxW / logo.w, boxH / logo.h) * fit;
  const w = logo.w * s;
  const h = logo.h * s;
  return (
    <InkPrint x={(SW - 14 - w) / 2} y={(SH - 14 - h) / 2} w={w} h={h} ink={INDIGO} seed={seed} rough={0.7} wear={0.15} misregister={0.5}>
      <svg
        width={w}
        height={h}
        viewBox={logo.box}
        fill="currentColor"
        style={{ position: "absolute", left: 0, top: 0 }}
        dangerouslySetInnerHTML={{ __html: logo.svg }}
      />
    </InkPrint>
  );
};

// Clay lands on the stamp stock as CLAY, in two passes that multiply to it (compensated for #EFE9DB, not the mint page):
// a flat pale tint, then the rough coat. The coat's dry patches show the tint, not bare paper, so its mask tile does not
// read as a repeat across the block.
const CLAY_TINT = "#F7C9B9";
const CLAY_COAT = "#EFA086";
// assets_raw/anthropic/Anthropic_wordmark_lobehub.svg, viewBox 0 0 182 24.
const WORDMARK = "M38.247 15.874L29.553 2.338H24.86v19.337h4.002V8.139l8.694 13.536h4.693V2.338h-4.003v13.536zm7.313-9.807h6.487v15.608h4.14V6.067h6.487v-3.73H45.56v3.73zm33.686 3.978h-9.109V2.338h-4.14v19.337h4.14v-7.9h9.109v7.9h4.14V2.338h-4.14v7.707zm13.39-3.978h5.108c2.043 0 3.12.746 3.12 2.155 0 1.408-1.077 2.154-3.12 2.154h-5.107v-4.31zm12.37 2.155c0-3.647-2.679-5.884-7.068-5.884h-9.443v19.337h4.142v-7.57h4.61l4.142 7.57h4.583l-4.586-8.146c2.302-.885 3.62-2.75 3.62-5.307zm12.686 9.91c-3.257 0-5.244-2.32-5.244-6.104 0-3.84 1.987-6.16 5.244-6.16 3.23 0 5.189 2.32 5.189 6.16 0 3.784-1.96 6.105-5.189 6.105zm0-16.132c-5.575 0-9.522 4.144-9.522 10.028 0 5.828 3.947 9.972 9.522 9.972 5.547 0 9.466-4.144 9.466-9.972C127.158 6.144 123.24 2 117.692 2zm22.59 8.929h-5.109V6.067h5.11c2.043 0 3.12.829 3.12 2.43 0 1.603-1.077 2.432-3.12 2.432zm.194-8.591h-9.445v19.337h4.142v-7.017h5.303c4.39 0 7.07-2.32 7.07-6.16 0-3.84-2.68-6.16-7.07-6.16zm35.108 12.839c-.718 1.878-2.153 2.956-4.113 2.956-3.257 0-5.244-2.32-5.244-6.105 0-3.84 1.987-6.16 5.244-6.16 1.96 0 3.395 1.077 4.113 2.955h4.388C178.896 4.68 175.667 2 171.472 2c-5.576 0-9.523 4.144-9.523 10.028 0 5.828 3.947 9.972 9.522 9.972 4.223 0 7.453-2.707 8.529-6.823h-4.416zm-26.39-12.84l7.705 19.338h4.225L153.42 2.338h-4.225zM9.277 14.024l2.636-6.796 2.637 6.796H9.276zm.428-11.685L2 21.675h4.307l1.576-4.06h8.06l1.575 4.06h4.307L14.121 2.338H9.704z";
const WORD_W = 620;
const WORD_S = WORD_W / 182;
const WORD_X = XM + T / 2 - WORD_W / 2;
const WORD_Y = (YM + Y2) / 2 - 12 * WORD_S;
const MARK_W = 930;
const MARK_S = MARK_W / 24;
const MARK_X = XM - MARK_W / 2;
const MARK_Y = (Y0 + YM) / 2 - ((3.52 + 20) / 2) * MARK_S;
const CLAY_BOX = 40;
const HOLES: { x: number; y: number }[] = [
  ...Array.from({ length: 13 }, (_, i) => ({ x: XM, y: Y0 + (i + 0.5) * PITCH })),
  ...Array.from({ length: 13 }, (_, i) => ({ x: XM + (i + 0.5) * PITCH, y: YM })),
];

// The press's leading edge is streaked, not a ruled line: fixed teeth along it, in world px.
const TEETH = Array.from({ length: 34 }, (_, i) => (random(`quarter-tooth-${i}`) - 0.5) * (i % 2 ? 90 : 34));

const ClayPress: React.FC<{ frame: number }> = ({ frame }) => {
  const reach = frame < 144 ? 0 : interpolate(frame, [144, 162], [150, 4 * T + 320], { ...clamp, easing: Easing.bezier(0.3, 0.1, 0.55, 0.95) });
  if (reach <= 0) return null;
  const ox = X0 - 100;
  const oy = Y0 - 100;
  const box = 2 * T + 2 * CLAY_BOX;
  const art = (
    <svg width={box} height={box} viewBox={`${X0 - CLAY_BOX} ${Y0 - CLAY_BOX} ${box} ${box}`} style={{ position: "absolute", left: 0, top: 0 }}>
      <defs>
        <clipPath id="quarter-press">
          <polygon
            points={[
              `${ox},${oy}`,
              ...TEETH.map((off, i) => {
                const t = i / (TEETH.length - 1);
                return `${ox + reach * (1 - t) + off},${oy + reach * t + off}`;
              }),
            ].join(" ")}
          />
        </clipPath>
      </defs>
      <g clipPath="url(#quarter-press)">
        <path
          d={`M${X0 + B} ${Y0 + B}L${X2 - B} ${Y0 + B}L${X2 - B} ${Y2 - B}L${XM + B} ${Y2 - B}L${XM + B} ${YM - B}L${X0 + B} ${YM - B}Z`}
          fill="currentColor"
        />
        {/* the mark is bare stamp paper: the press leaves it unprinted */}
        <g transform={`translate(${MARK_X} ${MARK_Y}) scale(${MARK_S})`}>
          <path d={MARK} fill="#fff" fillRule="evenodd" />
        </g>
        <g transform={`translate(${WORD_X} ${WORD_Y}) scale(${WORD_S})`}>
          <path d={WORDMARK} fill="#fff" fillRule="evenodd" />
        </g>
        {/* no ink lands where the seams' perforations are holes */}
        {HOLES.map((h) => (
          <circle key={`${h.x}-${h.y}`} cx={h.x} cy={h.y} r={PITCH * 0.3 + 1.2} fill="#fff" />
        ))}
      </g>
    </svg>
  );
  return (
    <>
      <div style={{ position: "absolute", left: X0 - CLAY_BOX, top: Y0 - CLAY_BOX, width: box, height: box, color: CLAY_TINT, mixBlendMode: "multiply" }}>{art}</div>
      <InkPrint x={X0 - CLAY_BOX} y={Y0 - CLAY_BOX} w={box} h={box} ink={CLAY_COAT} theme="offwhite" seed="clay" rough={1.4} wear={0.12} misregister={0.9}>
        {art}
      </InkPrint>
    </>
  );
};

const BlankTile: React.FC<{ frame: number; x: number; y: number; dx: number; dy: number; start: number; dur: number; seed: string }> = ({ frame, x, y, dx, dy, start, dur, seed }) => {
  if (frame <= start) return null;
  const t = slide(frame, start, dur);
  return <Stamp x={x + dx * (1 - t)} y={y + dy * (1 - t)} w={T} h={T} border={0} pitch={PITCH} window="transparent" seed={seed} />;
};

const QuarterOfAnthropic: React.FC<z.infer<typeof schema>> = ({ bands }) => {
  const frame = useCurrentFrame();
  const cam = camAt(frame);
  const flatten = interpolate(frame, [80, 104], [1, 0.3], clamp);
  return (
    <>
      <WipFilmLife frame={frame}>
        <PaperGround cam={cam} />
        <WipPlane cam={cam} d={GROUND_D}>
          <CutOut src="wip-anthropic/quarter_ground_day.png" x={GROUND_X} y={GROUND_TOP + GROUND_W / GROUND_ASPECT / 2} w={GROUND_W} aspect={GROUND_ASPECT} border={7} lift={0.25} seed="sf-ground" />
        </WipPlane>
        <WipPlane cam={cam}>
          <Stamp x={CX} y={CY} w={T} h={T} border={B} pitch={PITCH} seed="sf-tile">
            <PrintPhoto src="wip-anthropic/quarter_sf_night.png" seed="sf-print" />
          </Stamp>
          {DEAL.map(({ name, col, row, contact, fit }) => {
            const fall = contact < 40 ? 8 : 6;
            if (frame < contact - fall) return null;
            const press = stampPress(frame, contact, fall);
            const c = stampCentre(col, row);
            const up = 1 - Math.min(1, press / 0.7);
            return (
              <Stamp
                key={name}
                x={c.x}
                y={c.y}
                w={SW}
                h={SH}
                border={7}
                pitch={SH / 9}
                press={press}
                from={{ x: 1000, y: -260 }}
                rotate={11 * up}
                shadow={flatten}
                window="transparent"
                seed={name}
              >
                <Logo name={name} fit={fit} seed={`logo-${name === "Lyft" ? "d" : name === "Yelp" ? "e" : "b"}-${name}`} />
              </Stamp>
            );
          })}
        </WipPlane>
        <WipPlane cam={cam}>
          <BlankTile frame={frame} x={CX} y={CY - T} dx={0} dy={-1180} start={102} dur={20} seed="tile-top" />
          <BlankTile frame={frame} x={CX + T} y={CY} dx={1120} dy={0} start={104} dur={20} seed="tile-right" />
          <BlankTile frame={frame} x={CX + T} y={CY - T} dx={980} dy={-980} start={106} dur={18} seed="tile-diag" />
        </WipPlane>
        <WipPlane cam={cam} ink>
          <ClayPress frame={frame} />
        </WipPlane>
      </WipFilmLife>
      <CaptionBandsDebug on={bands} />
    </>
  );
};

export default QuarterOfAnthropic;
